import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/NavigateButton'
import { getComments, getPost, getPosts, type Post } from '@/lib/posts'

// ISR: regenerate each post at most every 5 minutes.
export const revalidate = 300

// Params not returned by generateStaticParams are rendered on demand
// (equivalent to `fallback: 'blocking'`).
export const dynamicParams = true

const fetchOptions = { next: { revalidate: 300 } }

export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts = await getPosts(fetchOptions)

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

async function getPostOrNotFound(id: string): Promise<Post> {
  try {
    return await getPost(id, fetchOptions)
  } catch {
    notFound()
  }
}

export async function generateMetadata({
  params,
}: PageProps<'/blog/[id]'>): Promise<Metadata> {
  const { id } = await params
  const post = await getPostOrNotFound(id)
  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPost({ params }: PageProps<'/blog/[id]'>) {
  const { id } = await params

  const [post, comments] = await Promise.all([
    getPostOrNotFound(id),
    getComments(id, fetchOptions).catch(() => notFound()),
  ])

  return (
    <article>
      <BackButton>← Back</BackButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

